-- S05 (failed at compile, counted): first try of the FEC duplicate check; a correlated subquery in the select list was not allowed. Rerun as S06.
-- FEC bulk vs the three other committee-master tables: is it the same rows as one cycle? (duplicate-load trap check)
WITH b AS (SELECT FEC_CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK)
, p AS (SELECT CYCLE, CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_COMMITTEE)
, f AS (SELECT CYCLE, FEC_CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK_COMMITTEES)
, c AS (SELECT CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES)
SELECT 'POLITICS__FEC_COMMITTEE' other, p.CYCLE::varchar cyc, (SELECT COUNT(*) FROM p p2 WHERE p2.CYCLE = p.CYCLE) other_rows, COUNT(*) id_hits,
       COUNT_IF(EQUAL_NULL(b.nm, p.nm) AND EQUAL_NULL(b.tr, p.tr) AND EQUAL_NULL(b.ff, p.ff)) same_nm_tr_ff
FROM b JOIN p ON b.id = p.id GROUP BY p.CYCLE
UNION ALL
SELECT 'FINANCE__FED_FEC_BULK_COMMITTEES', f.CYCLE::varchar, (SELECT COUNT(*) FROM f f2 WHERE f2.CYCLE = f.CYCLE), COUNT(*),
       COUNT_IF(EQUAL_NULL(b.nm, f.nm) AND EQUAL_NULL(b.tr, f.tr) AND EQUAL_NULL(b.ff, f.ff))
FROM b JOIN f ON b.id = f.id GROUP BY f.CYCLE
UNION ALL
SELECT 'FINANCE__FED_FEC_COMMITTEES', 'n/a', (SELECT COUNT(*) FROM c), COUNT(*),
       COUNT_IF(EQUAL_NULL(b.nm, c.nm) AND EQUAL_NULL(b.tr, c.tr) AND EQUAL_NULL(b.ff, c.ff))
FROM b JOIN c ON b.id = c.id
ORDER BY 1, 2;

-- S06 FEC bulk: overlap with the three other committee-master tables, by cycle (duplicate check)  [4 rows, 0.6s, qid 01c74b9c-040b-a5ce-0026-eed301332d9a]
-- FEC bulk vs the three other committee-master tables: is it the same rows as one cycle? (duplicate-load trap check)
WITH b AS (SELECT FEC_CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK)
, o AS (
  SELECT 'POLITICS__FEC_COMMITTEE' src, CYCLE::varchar cyc, CMTE_ID id, UPPER(TRIM(CMTE_NM)) nm, UPPER(TRIM(TRES_NM)) tr, CMTE_FILING_FREQ ff FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_COMMITTEE
  UNION ALL SELECT 'FINANCE__FED_FEC_BULK_COMMITTEES', CYCLE::varchar, FEC_CMTE_ID, UPPER(TRIM(CMTE_NM)), UPPER(TRIM(TRES_NM)), CMTE_FILING_FREQ FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK_COMMITTEES
  UNION ALL SELECT 'FINANCE__FED_FEC_COMMITTEES', 'n/a', CMTE_ID, UPPER(TRIM(CMTE_NM)), UPPER(TRIM(TRES_NM)), CMTE_FILING_FREQ FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES)
SELECT o.src, o.cyc, COUNT(*) other_rows, COUNT(b.id) id_hits,
       COUNT_IF(b.id IS NOT NULL AND EQUAL_NULL(b.nm, o.nm) AND EQUAL_NULL(b.tr, o.tr) AND EQUAL_NULL(b.ff, o.ff)) same_nm_tr_ff
FROM o LEFT JOIN b ON b.id = o.id
GROUP BY 1, 2 ORDER BY 1, 2;

-- S07 FEC bulk: candidate committees + latest election year + 2024/2026 money (zombie-campaign extract)  [7935 rows, 1.5s, qid 01c74b9c-040b-a029-0026-eed30133b86a]
-- FEC bulk (2024 committee file) candidate committees -> candidate's latest election year -> 2024 and 2026 money totals; plus whether the same name runs under another candidate ID (zombie-campaign test)
WITH b AS (SELECT FEC_CMTE_ID, CMTE_NM, TRES_NM, CMTE_DSGN, CMTE_TP, CMTE_FILING_FREQ, CMTE_ST, TRIM(FEC_CAND_ID) cand
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK WHERE CMTE_DSGN IN ('P','A') AND NULLIF(TRIM(FEC_CAND_ID),'') IS NOT NULL)
, c AS (SELECT CAND_ID, MAX(TRY_TO_NUMBER(CAND_ELECTION_YR::varchar)) last_yr, MAX(CYCLE) last_cycle, MAX(CAND_NAME) cand_name,
               MAX(OFFICE) office, MAX(OFFICE_STATE) ost, LISTAGG(DISTINCT CAND_STATUS, ',') statuses
        FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_CANDIDATE GROUP BY 1)
, other AS (SELECT UPPER(TRIM(CAND_NAME)) nm, CAND_ID, TRY_TO_NUMBER(CAND_ELECTION_YR::varchar) yr FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_CANDIDATE)
, s AS (SELECT CAND_ID, CYCLE, TRY_TO_DOUBLE(TTL_RECEIPTS::varchar) rec, TRY_TO_DOUBLE(TTL_DISB::varchar) disb, TRY_TO_DOUBLE(TTL_INDIV_CONTRIB::varchar) indiv,
               TRY_TO_DOUBLE(CASH_ON_HAND_CLOSE::varchar) coh, TRY_TO_DOUBLE(TRANS_TO_AUTH::varchar) to_auth, INCUMBENT_CHALLENGER ic, COVERAGE_END_DATE::varchar cvg
        FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_CANDIDATE_SUMMARY)
SELECT b.*, c.last_yr, c.last_cycle, c.cand_name, c.office, c.ost, c.statuses,
       (SELECT MAX(o.yr) FROM other o WHERE o.nm = UPPER(TRIM(c.cand_name)) AND o.CAND_ID <> b.cand) other_id_max_yr,
       s24.rec rec24, s24.disb disb24, s24.indiv indiv24, s24.coh coh24, s24.to_auth to_auth24, s24.ic ic24, s24.cvg cvg24,
       s26.rec rec26, s26.disb disb26, s26.coh coh26, s26.ic ic26, s26.cvg cvg26
FROM b LEFT JOIN c ON c.CAND_ID = b.cand
LEFT JOIN s s24 ON s24.CAND_ID = b.cand AND s24.CYCLE = 2024
LEFT JOIN s s26 ON s26.CAND_ID = b.cand AND s26.CYCLE = 2026;

