-- S09 (failed at compile, counted): first try of the derivative-table profile; the table has no _SOURCE_RUN_ID column. Rerun as S10. Text as sent (reconstructed from S10, which differs only in the dropped column and the date parse):
-- SEC derivative trades: size, key uniqueness, whole-row duplicates, date junk, code mix, self-reported late flag
WITH t AS (SELECT *, TRY_TO_DATE(TRANS_DATE, 'DD-MON-YYYY') td,
                  HASH(ACCESSION_NUMBER, SECURITY_TITLE, TRANS_DATE, TRANS_CODE, TRANS_SHARES, CONV_EXERCISE_PRICE, TRANS_PRICEPERSHARE, TRANS_ACQUIRED_DISP_CD, EXPIRATION_DATE, UNDLYNG_SEC_SHARES, SHRS_OWND_FOLWNG_TRANS, DIRECT_INDIRECT_OWNERSHIP) h
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS)
SELECT COUNT(*) n, COUNT(DISTINCT ACCESSION_NUMBER) filings, COUNT(DISTINCT DERIV_TRANS_SK) sks, COUNT(DISTINCT ACCESSION_NUMBER, DERIV_TRANS_SK) acc_sk,
       COUNT(DISTINCT h) distinct_content, COUNT(DISTINCT _SOURCE_RUN_ID) runs,
       COUNT_IF(td IS NULL AND NULLIF(TRIM(TRANS_DATE),'') IS NOT NULL) date_unparsed, COUNT_IF(NULLIF(TRIM(TRANS_DATE),'') IS NULL) date_blank,
       MIN(td) d0, MAX(td) d1, COUNT_IF(YEAR(td) < 2000) pre2000, COUNT_IF(td > '2026-09-24') future,
       APPROX_TOP_K(YEAR(td), 12) years, APPROX_TOP_K(TRANS_CODE, 15) codes, APPROX_TOP_K(TRANS_FORM_TYPE, 5) forms,
       APPROX_TOP_K(TRANS_TIMELINESS, 5) timeliness, APPROX_TOP_K(EQUITY_SWAP_INVOLVED, 5) swap
FROM t;

-- S10 SEC deriv: size, key uniqueness, whole-row duplicates, date junk, code mix  [1 rows, 1.3s, qid 01c74ba1-040b-a028-0026-eed30133d7be]
-- SEC derivative trades: size, key uniqueness, whole-row duplicates, date junk, code mix, self-reported late flag
WITH t AS (SELECT *, COALESCE(TRY_TO_DATE(TRANS_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(TRANS_DATE::varchar)) td,
                  HASH(ACCESSION_NUMBER, SECURITY_TITLE, TRANS_DATE, TRANS_CODE, TRANS_SHARES, CONV_EXERCISE_PRICE, TRANS_PRICEPERSHARE, TRANS_ACQUIRED_DISP_CD, EXPIRATION_DATE, UNDLYNG_SEC_SHARES, SHRS_OWND_FOLWNG_TRANS, DIRECT_INDIRECT_OWNERSHIP) h
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS)
SELECT COUNT(*) n, COUNT(DISTINCT ACCESSION_NUMBER) filings, COUNT(DISTINCT DERIV_TRANS_SK) sks, COUNT(DISTINCT ACCESSION_NUMBER, DERIV_TRANS_SK) acc_sk,
       COUNT(DISTINCT h) distinct_content,
       COUNT_IF(td IS NULL AND NULLIF(TRIM(TRANS_DATE::varchar),'') IS NOT NULL) date_unparsed, COUNT_IF(NULLIF(TRIM(TRANS_DATE::varchar),'') IS NULL) date_blank,
       MIN(td) d0, MAX(td) d1, COUNT_IF(YEAR(td) < 2000) pre2000, COUNT_IF(td > '2026-09-24') future,
       APPROX_TOP_K(YEAR(td), 12) years, APPROX_TOP_K(TRANS_CODE, 15) codes, APPROX_TOP_K(TRANS_FORM_TYPE, 5) forms,
       APPROX_TOP_K(TRANS_TIMELINESS, 5) timeliness, APPROX_TOP_K(EQUITY_SWAP_INVOLVED, 5) swap
FROM t;

-- S11 SEC deriv x submission: trade-to-filing lag on Form 4 lines, per issuer per trade year (late = >6 calendar days)  [42010 rows, 4.4s, qid 01c74ba2-040b-a027-0026-eed3013406ce]
-- SEC deriv x insider submission (ACCESSION_NUMBER): days from trade to filing on original Form 4s, per issuer per trade year. Late = filed more than 6 calendar days after the trade (the rule is 2 business days, so this undercounts).
WITH d AS (SELECT ACCESSION_NUMBER, TRANS_CODE, TRANS_TIMELINESS,
                  COALESCE(TRY_TO_DATE(TRANS_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(TRANS_DATE::varchar)) td,
                  TRY_TO_DOUBLE(CONV_EXERCISE_PRICE::varchar) px
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS WHERE TRANS_FORM_TYPE = '4')
, s AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(FILING_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(FILING_DATE::varchar)) fd,
               DOCUMENT_TYPE, TRY_TO_NUMBER(ISSUER_CIK::varchar) cik, ISSUER_NAME, ISSUER_TICKER
        FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION)
, j AS (SELECT d.*, s.fd, s.DOCUMENT_TYPE, s.cik, s.ISSUER_NAME, s.ISSUER_TICKER, DATEDIFF(day, d.td, s.fd) lag,
               (d.TRANS_CODE = 'A' AND d.px > 0) is_grant
        FROM d JOIN s ON s.ACCESSION_NUMBER = d.ACCESSION_NUMBER)
SELECT cik, YEAR(td) yr, MAX(ISSUER_NAME) issuer, MAX(ISSUER_TICKER) ticker, DOCUMENT_TYPE doc,
       COUNT(*) n, COUNT(DISTINCT ACCESSION_NUMBER) filings,
       COUNT_IF(lag > 6) late6, COUNT_IF(lag > 30) late30, COUNT_IF(lag < 0) neg_lag, COUNT_IF(TRANS_TIMELINESS = 'L') self_late, COUNT_IF(lag > 6 AND TRANS_TIMELINESS = 'L') late6_self,
       COUNT_IF(is_grant) grants, COUNT_IF(is_grant AND lag > 6) grants_late6, COUNT_IF(is_grant AND lag > 30) grants_late30,
       COUNT(DISTINCT IFF(is_grant AND lag > 6, ACCESSION_NUMBER, NULL)) grant_filings_late6, MEDIAN(IFF(is_grant, lag, NULL)) grant_med_lag, MAX(IFF(is_grant, lag, NULL)) grant_max_lag
FROM j WHERE td BETWEEN '2014-01-01' AND '2025-12-31'
GROUP BY 1, 2, 5;

-- S12 SEC deriv: line detail for the 10 issuers with most late option-award lines  [4427 rows, 1.4s, qid 01c74ba3-040b-a027-0026-eed3013406e6]
-- SEC deriv: the line-level detail behind the 10 issuers with the most late option-award lines at a 50%+ late rate (read the rows; stock-dividend adjustment or a real award?)
WITH s AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(FILING_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(FILING_DATE::varchar)) fd, DOCUMENT_TYPE,
                  TRY_TO_NUMBER(ISSUER_CIK::varchar) cik, ISSUER_NAME, REMARKS
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION
           WHERE TRY_TO_NUMBER(ISSUER_CIK::varchar) IN (318673, 1397047, 1260968, 930775, 1580149, 1045942, 1360565, 894871, 1368637, 87802))
, o AS (SELECT ACCESSION_NUMBER, LISTAGG(DISTINCT OWNER_NAME || ' (' || COALESCE(RELATIONSHIP,'') || ')', '; ') owners
        FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_REPORTINGOWNER WHERE ACCESSION_NUMBER IN (SELECT ACCESSION_NUMBER FROM s) GROUP BY 1)
SELECT s.cik, s.ISSUER_NAME, s.DOCUMENT_TYPE, s.fd, d.ACCESSION_NUMBER,
       COALESCE(TRY_TO_DATE(d.TRANS_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(d.TRANS_DATE::varchar)) td, d.TRANS_CODE, d.TRANS_TIMELINESS,
       d.SECURITY_TITLE, d.CONV_EXERCISE_PRICE, d.TRANS_SHARES, d.TRANS_PRICEPERSHARE, d.TRANS_ACQUIRED_DISP_CD, d.EXCERCISE_DATE, d.EXPIRATION_DATE,
       d.UNDLYNG_SEC_SHARES, d.SHRS_OWND_FOLWNG_TRANS, o.owners, LEFT(s.REMARKS, 300) remarks
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS d JOIN s ON s.ACCESSION_NUMBER = d.ACCESSION_NUMBER
LEFT JOIN o ON o.ACCESSION_NUMBER = d.ACCESSION_NUMBER
ORDER BY s.cik, td;

-- S13 SEC deriv: option awards deduped to first report, lag per issuer per year (trades 2017-01 to 2024-09)  [16735 rows, 2.5s, qid 01c74ba4-040b-9fb8-0026-eed3013436a6]
-- SEC deriv: option awards deduped to first report. Key = issuer + owner + trade date + expiration + exercise price + title; lag = first original Form 4 filing date minus trade date. Trades 2017-01-01 to 2024-09-30 only, so a first report falls inside the loaded filing window.
WITH s AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(FILING_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(FILING_DATE::varchar)) fd,
                  DOCUMENT_TYPE, TRY_TO_NUMBER(ISSUER_CIK::varchar) cik, ISSUER_NAME, ISSUER_TICKER
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION)
, o AS (SELECT ACCESSION_NUMBER, MIN(TRY_TO_NUMBER(OWNER_CIK::varchar)) owner_cik FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_REPORTINGOWNER GROUP BY 1)
, d AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(TRANS_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(TRANS_DATE::varchar)) td,
               TRY_TO_DOUBLE(CONV_EXERCISE_PRICE::varchar) px, UPPER(REGEXP_REPLACE(SECURITY_TITLE, '[^A-Za-z]', '')) ttl, EXPIRATION_DATE::varchar exp
        FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS WHERE TRANS_CODE = 'A' AND TRY_TO_DOUBLE(CONV_EXERCISE_PRICE::varchar) > 0)
, a AS (SELECT s.cik, o.owner_cik, d.td, d.exp, d.px, d.ttl, MIN(s.fd) first_fd, MAX(s.ISSUER_NAME) issuer, MAX(s.ISSUER_TICKER) ticker, COUNT(*) lines
        FROM d JOIN s ON s.ACCESSION_NUMBER = d.ACCESSION_NUMBER LEFT JOIN o ON o.ACCESSION_NUMBER = d.ACCESSION_NUMBER
        WHERE d.td BETWEEN '2017-01-01' AND '2024-09-30' AND s.DOCUMENT_TYPE IN ('4', '5')
        GROUP BY 1, 2, 3, 4, 5, 6)
SELECT cik, YEAR(td) yr, MAX(issuer) issuer, MAX(ticker) ticker, COUNT(*) awards, SUM(lines) lines,
       COUNT_IF(DATEDIFF(day, td, first_fd) > 6) late6, COUNT_IF(DATEDIFF(day, td, first_fd) > 30) late30, COUNT_IF(DATEDIFF(day, td, first_fd) > 365) late365,
       COUNT(DISTINCT owner_cik) owners, COUNT(DISTINCT IFF(DATEDIFF(day, td, first_fd) > 30, owner_cik, NULL)) owners_late30,
       MEDIAN(DATEDIFF(day, td, first_fd)) med_lag, MAX(DATEDIFF(day, td, first_fd)) max_lag
FROM a GROUP BY 1, 2;

-- S14 SEC deriv: option awards deduped v2 (no price in key, pre-first-filing awards dropped), per issuer per year  [16735 rows, 2.9s, qid 01c74ba5-040b-a911-0026-eed301344672]
-- SEC deriv: option awards deduped to first report, v2. Key drops exercise price (stock-dividend re-reports change it) = issuer + owner + trade date + expiration + title. Awards dated before the issuer's first filing in the insider table are dropped (pre-IPO / pre-registration awards). Trades 2017-01-01 to 2024-09-30.
WITH s AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(FILING_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(FILING_DATE::varchar)) fd,
                  DOCUMENT_TYPE, TRY_TO_NUMBER(ISSUER_CIK::varchar) cik, ISSUER_NAME, ISSUER_TICKER
           FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION)
, f AS (SELECT cik, MIN(fd) issuer_first_fd FROM s GROUP BY 1)
, o AS (SELECT ACCESSION_NUMBER, MIN(TRY_TO_NUMBER(OWNER_CIK::varchar)) owner_cik FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_REPORTINGOWNER GROUP BY 1)
, d AS (SELECT ACCESSION_NUMBER, COALESCE(TRY_TO_DATE(TRANS_DATE::varchar, 'DD-MON-YYYY'), TRY_TO_DATE(TRANS_DATE::varchar)) td,
               UPPER(REGEXP_REPLACE(SECURITY_TITLE, '[^A-Za-z]', '')) ttl, EXPIRATION_DATE::varchar exp
        FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_DERIV_TRANS WHERE TRANS_CODE = 'A' AND TRY_TO_DOUBLE(CONV_EXERCISE_PRICE::varchar) > 0)
, a AS (SELECT s.cik, o.owner_cik, d.td, d.exp, d.ttl, MIN(s.fd) first_fd, MAX(s.ISSUER_NAME) issuer, MAX(s.ISSUER_TICKER) ticker, COUNT(*) lines
        FROM d JOIN s ON s.ACCESSION_NUMBER = d.ACCESSION_NUMBER LEFT JOIN o ON o.ACCESSION_NUMBER = d.ACCESSION_NUMBER
        WHERE d.td BETWEEN '2017-01-01' AND '2024-09-30' AND s.DOCUMENT_TYPE IN ('4', '5')
        GROUP BY 1, 2, 3, 4, 5)
SELECT a.cik, YEAR(a.td) yr, MAX(a.issuer) issuer, MAX(a.ticker) ticker, MAX(f.issuer_first_fd) issuer_first_fd,
       COUNT_IF(a.td < f.issuer_first_fd) pre_first_dropped,
       COUNT_IF(a.td >= f.issuer_first_fd) awards, SUM(IFF(a.td >= f.issuer_first_fd, lines, 0)) lines,
       COUNT_IF(a.td >= f.issuer_first_fd AND DATEDIFF(day, a.td, a.first_fd) > 6) late6,
       COUNT_IF(a.td >= f.issuer_first_fd AND DATEDIFF(day, a.td, a.first_fd) > 30) late30,
       COUNT_IF(a.td >= f.issuer_first_fd AND DATEDIFF(day, a.td, a.first_fd) > 365) late365,
       COUNT(DISTINCT IFF(a.td >= f.issuer_first_fd, a.owner_cik, NULL)) owners,
       COUNT(DISTINCT IFF(a.td >= f.issuer_first_fd AND DATEDIFF(day, a.td, a.first_fd) > 30, a.owner_cik, NULL)) owners_late30,
       MEDIAN(IFF(a.td >= f.issuer_first_fd, DATEDIFF(day, a.td, a.first_fd), NULL)) med_lag,
       MAX(IFF(a.td >= f.issuer_first_fd, DATEDIFF(day, a.td, a.first_fd), NULL)) max_lag
FROM a JOIN f ON f.cik = a.cik GROUP BY 1, 2;

